# region: digest
def digest(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: shape
def shape(xs, offset=-1):
    return [v - offset for v in xs]

# region: fold
def fold(xs):
    return [v for v in xs if v % 2 == 0]

# region: intake
def intake(xs):
    return [v * v for v in xs]

# region: gather
def gather(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: emit
def emit(summary):
    out = dict(summary)
    out['flags'] = sorted(k for k, v in summary.items() if isinstance(v, int) and v > 0)
    return out

# region: run
def run(raw):
    return emit(gather(intake(fold(shape(digest(raw))))))

